package com.ikeriano.pasapalabra3d;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import android.content.*;
public class BibliotecaActivity extends Activity{@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,32,32,32);TextView t=new TextView(this);t.setText("Biblioteca de Pasapalabra 3D 0.37\n\n3 programas completos de Telecinco, 3 vídeos adicionales y 17 pruebas. Todo sin internet.\n\nNo es el juego: instala también Pasapalabra 3D 0.37 y abre «Telecinco · Programas completos».\n\nLos comentarios y los personajes nuevos son 🆕 INVENTADO.");t.setTextSize(20);l.addView(t);Button x=new Button(this);x.setText("Abrir Pasapalabra 3D");x.setOnClickListener(v->{try{Intent i=new Intent();i.setClassName("com.ikeriano.pasapalabra3d.gb","com.ikeriano.pasapalabra3d.MainActivity");startActivity(i);}catch(Exception e){Toast.makeText(this,"Instala primero Pasapalabra 3D 0.37.",Toast.LENGTH_LONG).show();}});l.addView(x);setContentView(l);}}
